#' Ternary diagrams with the CI_Method function results
#'
#' Visualizes Conservativeness Index (CI) predictions using ternary diagrams. Incorporates 
#' advanced hierarchical clustering to automatically group and color-code structurally 
#' similar apportionment solutions.
#'
#' @param data List. The output generated by the CI_Method function.
#' @param tracers Numeric vector. Indices of the tracers to display. Default 1:4.
#' @param n_row Integer. Number of rows in the output grid layout. Default 1.
#' @param n_col Integer. Number of columns in the output grid layout. Default 2.
#' @param Means Logical. If TRUE, indicates the input utilizes mean and SD formats rather than raw observations. Default FALSE.
#' @param cluster Logical. If TRUE, applies hierarchical clustering to group structurally similar ternary solutions. Default FALSE.
#' @param dendro_lvls Integer. Number of branch levels to cut the clustering dendrogram. Default 5.
#' @param vrtl_sol Logical. If TRUE, overlays a theoretical or target virtual solution on the plot. Default FALSE.
#' @param vrtl Numeric vector. Apportionment values for the theoretical solution. Default c(0.05, 0.9, 0.05).
#' @param seed Integer. Random seed for reproducible cluster ordering when cluster = TRUE. Default NULL.
#' 
#' @return No return value, called for side effects (draws ternary diagrams
#'   of the individual tracer predictions on the current graphics device).
#'
#'
#' @export
#' 
Ternary_Plot <- function(data, tracers = 1:(length(data) - 2), n_row = 4, n_col = 5, Means = FALSE, cluster = FALSE,
                         dendro_lvls = 5, vrtl_sol = FALSE, vrtl = c(1, 0, 0), seed = NULL) {
  
  sources <- nrow(inputSource(data[[length(data) - 1]]))
  
  oldpar <- par(no.readonly = TRUE)
  on.exit(par(oldpar))
  
  if (sources == 3) {
    if (Means == TRUE) {
      if (cluster == TRUE){
        ######### Cluster ########################################################  
        df <- as.data.frame(data[(length(data)-1)])
        colnames(df) <- sub("^DB\\.", "", colnames(df))
        
        df <- df[c(1:nrow(df)-1),]
        
        # Generate synthetic data for each element
        if (!is.null(seed)) set.seed(seed)
        synthetic_data <- df %>%
          rowwise() %>%
          mutate(
            across(starts_with("SD_"), ~ list(rnorm(n[1], mean = get(paste0("Mean_", sub("^SD_", "", cur_column()))), sd = .)),
                   .names = "{.col}_synthetic")
          ) %>%
          ungroup() %>%
          # Select synthetic columns
          select(ends_with("_synthetic")) %>%
          # Unnest synthetic columns
          unnest(cols = everything()) %>%
          # Rename columns to remove "D" prefix and "_synthetic" suffix
          rename_with(~ gsub("^SD_|_synthetic$", "", .x))
        
        # Select numeric columns (excluding the first three columns)
        numeric_columns <- df %>% select(-(1:2)) %>% select_if(is.numeric)
        
        # Compute the correlation matrix
        correlation_matrix <- cor(synthetic_data, use = "pairwise.complete.obs")
        
        # Create a hierarchical clustering dendrogram
        hc <- hclust(as.dist(1 - correlation_matrix), method = "ward.D2")#"complete"
        
        # Cut the dendrogram at different levels
        clusters_levels <- cutree(hc, k = dendro_lvls) 
        
        # Set the color palette for the correlation plot
        color_palette <- colorRampPalette(c("darkgreen", "orange", "purple"))(dendro_lvls)
        
        data[1:(length(data)-2)] <- data[hc$order]
        
        # Create a logical vector for column selection
        cols_to_keep <- !(seq_len(ncol(data[[length(data) - 1]])) %in% c(1, 2, ncol(data[[length(data) - 1]])) | grepl("^D", colnames(data[[length(data) - 1]])))
        
        # Get the selected column names
        t_names <- gsub("^[Mm]ean_", "", colnames(data[[length(data) - 1]])[cols_to_keep])
        t_names[1:length(t_names)] <- t_names[hc$order]
        
      } else{
        t_names <- gsub("^[Mm]ean_", "", colnames(data[[length(data) - 1]][3:(ncol(data[[length(data) - 1]]) - 3)]))
        # Set a default color (e.g., blue) for non-clustered plots
        color_palette <- rep("blue", length(tracers))
      }  
      ################################################################################  
      
    } else { # Means == F
      if (cluster == TRUE){
        ######### Cluster ########################################################  
        df <- as.data.frame(data[(length(data)-1)])
        colnames(df) <- sub("^DB\\.", "", colnames(df))
        
        # Select numeric columns (excluding the first three columns)
        numeric_columns <- df %>% select(-(1:2)) %>% select_if(is.numeric)
        
        # Compute the correlation matrix
        correlation_matrix <- cor(numeric_columns, use = "pairwise.complete.obs")
        
        # Create a hierarchical clustering dendrogram
        hc <- hclust(as.dist(1 - correlation_matrix), method = "ward.D2")#"complete"
        
        # Cut the dendrogram at different levels
        clusters_levels <- cutree(hc, k = dendro_lvls) 
        
        # Set the color palette for the correlation plot
        color_palette <- colorRampPalette(c("darkgreen", "orange", "purple"))(dendro_lvls)
        
        data[1:(length(data)-2)] <- data[hc$order]
        
        t_names <- gsub("^[Mm]ean_", "", colnames(data[[length(data) - 1]][3:ncol(data[[length(data) - 1]])]))
        t_names[1:length(t_names)] <- t_names[hc$order]
        
      } else {
        t_names <- gsub("^[Mm]ean_", "", colnames(data[[length(data) - 1]][3:ncol(data[[length(data) - 1]])]))
        # Set a default color (e.g., blue) for non-clustered plots
        color_palette <- rep("blue", length(tracers))
      }
      ################################################################################  
    } 
    
    plots <- list()
    par(mar = c(0, 0.1, 3, 0.1), mfcol = c(n_row, n_col))
    for (i2 in tracers) {
      result <- data[[i2]]
      if (ncol(result) < 5) next
      x <- result[, 3]
      y <- result[, 4]
      z <- result[, 5]
      
      x_vrt <- vrtl[1]
      y_vrt <- vrtl[2]
      z_vrt <- vrtl[3]
      
      test <- as.data.frame(cbind(x, y, z))
      if (ncol(test) >= 3 && nrow(test) > 0) {
        test <- test[complete.cases(test) & is.finite(rowSums(test)) &
                     test[,1] > -0.1 & test[,1] < 1.1 &
                     test[,2] > -0.1 & test[,2] < 1.1 &
                     test[,3] > -0.1 & test[,3] < 1.1, , drop = FALSE]
      } else { test <- data.frame() }
      test_vrt <- as.data.frame(cbind(x_vrt, y_vrt, z_vrt))
      
      plots[[i2]] <- TernaryPlot(xlim = c(-0.6, 0.6), tip.cex = 1, grid.lines = 4, grid.minor.lines = 1)
      if (cluster == TRUE) {
        if (nrow(test) > 0) TernaryPoints(test, col = alpha(color_palette[clusters_levels[t_names[[i2]]]], 0.5), cex = 0.1)
      } else {
        if (nrow(test) > 0) TernaryPoints(test, col = alpha('blue', 0.5), cex = 0.1)
      }
      if (vrtl_sol) {TernaryPoints(test_vrt, col = alpha('red', 0.9), cex = 0.8, pch = 23, bg = "black", lwd = 2)
      }
      title(t_names[i2], cex.main = 3.5)
    }
  } else if (sources == 4) {
    if (Means == TRUE) {
      if (cluster == TRUE) {
        ######### Cluster ########################################################  
        df <- as.data.frame(data[(length(data)-1)])
        colnames(df) <- sub("^DB\\.", "", colnames(df))
        
        df <- df[c(1:nrow(df)-1),]
        
        # Generate synthetic data for each element
        if (!is.null(seed)) set.seed(seed)
        synthetic_data <- df %>%
          rowwise() %>%
          mutate(
            across(starts_with("SD_"), ~ list(rnorm(n[1], mean = get(paste0("Mean_", sub("^SD_", "", cur_column()))), sd = .)),
                   .names = "{.col}_synthetic")
          ) %>%
          ungroup() %>%
          # Select synthetic columns
          select(ends_with("_synthetic")) %>%
          # Unnest synthetic columns
          unnest(cols = everything()) %>%
          # Rename columns to remove "D" prefix and "_synthetic" suffix
          rename_with(~ gsub("^SD_|_synthetic$", "", .x))
        
        # Select numeric columns (excluding the first three columns)
        numeric_columns <- df %>% select(-(1:2)) %>% select_if(is.numeric)
        
        # Compute the correlation matrix
        correlation_matrix <- cor(synthetic_data, use = "pairwise.complete.obs")
        
        # Create a hierarchical clustering dendrogram
        hc <- hclust(as.dist(1 - correlation_matrix), method = "ward.D2")#"complete"
        
        # Cut the dendrogram at different levels
        clusters_levels <- cutree(hc, k = dendro_lvls) 
        
        # Set the color palette for the correlation plot
        color_palette <- colorRampPalette(c("darkgreen", "orange", "purple"))(dendro_lvls)
        
        data[1:(length(data)-2)] <- data[hc$order]
        
        ################################################################################  
        # Create a logical vector for column selection
        cols_to_keep <- !(seq_len(ncol(data[[length(data) - 1]])) %in% c(1, 2, ncol(data[[length(data) - 1]])) | grepl("^D", colnames(data[[length(data) - 1]])))
        
        # Get the selected column names
        t_names <- gsub("^[Mm]ean_", "", colnames(data[[length(data) - 1]])[cols_to_keep])
        t_names[1:length(t_names)] <- t_names[hc$order]
        
      } else{ # cluster else
        t_names <- gsub("^[Mm]ean_", "", colnames(data[[length(data) - 1]][3:(ncol(data[[length(data) - 1]]) - 3)]))
        # Set a default color (e.g., blue) for non-clustered plots
        color_palette <- rep("blue", length(tracers))
      }                    
    } else { # Means else
      
      if (cluster == TRUE){
        ######### Cluster ########################################################  
        df <- as.data.frame(data[(length(data)-1)])
        colnames(df) <- sub("^DB\\.", "", colnames(df))
        
        # Select numeric columns (excluding the first three columns)
        numeric_columns <- df %>% select(-(1:2)) %>% select_if(is.numeric)
        
        # Compute the correlation matrix
        correlation_matrix <- cor(numeric_columns, use = "pairwise.complete.obs")
        
        # Create a hierarchical clustering dendrogram
        hc <- hclust(as.dist(1 - correlation_matrix), method = "ward.D2")#"complete"
        
        # Cut the dendrogram at different levels
        clusters_levels <- cutree(hc, k = dendro_lvls) 
        
        # Set the color palette for the correlation plot
        color_palette <- colorRampPalette(c("darkgreen", "orange", "purple"))(dendro_lvls)
        
        data[1:(length(data)-2)] <- data[hc$order]
        
        ################################################################################  
        
        t_names <- gsub("^[Mm]ean_", "", colnames(data[[length(data) - 1]][3:ncol(data[[length(data) - 1]])]))
        t_names[1:length(t_names)] <- t_names[hc$order]
      } else {
        t_names <- gsub("^[Mm]ean_", "", colnames(data[[length(data) - 1]][3:ncol(data[[length(data) - 1]])]))
        # Set a default color (e.g., blue) for non-clustered plots
        color_palette <- rep("blue", length(tracers))
      }
    }
    
    plots <- list()
    par(mar = c(0, 0.1, 3, 0.1), mfcol = c(6, n_col))
    for (i2 in tracers) {
      result <- data[[i2]]
      if (ncol(result) < 6) next
      w1 <- result[, 3]; w2 <- result[, 4]; w3 <- result[, 5]; w4 <- result[, 6]
      
      # Original triangles
      x <- w1;  y <- w2;  z <- w3 + w4
      x1 <- w2; y1 <- w3; z1 <- w1 + w4
      x2 <- w3; y2 <- w4; z2 <- w1 + w2
      x3 <- w4; y3 <- w1; z3 <- w2 + w3
      x4 <- w1; y4 <- w3; z4 <- w2 + w4
      x5 <- w2; y5 <- w4; z5 <- w1 + w3
      
      .filt3 <- function(a, b, cc) {
        df <- as.data.frame(cbind(a, b, cc))
        if (ncol(df) < 3 || nrow(df) == 0) return(data.frame())
        df[complete.cases(df) & is.finite(rowSums(df)) &
           df[,1] > -0.1 & df[,1] < 1.1 &
           df[,2] > -0.1 & df[,2] < 1.1 &
           df[,3] > -0.1 & df[,3] < 1.1, , drop = FALSE]
      }
      test  <- .filt3(x,  y,  z)
      test1 <- .filt3(x1, y1, z1)
      test2 <- .filt3(x2, y2, z2)
      test3 <- .filt3(x3, y3, z3)
      test4 <- .filt3(x4, y4, z4)
      test5 <- .filt3(x5, y5, z5)
      
      # Virtual sample
      x_vrt <- vrtl[1]
      y_vrt <- vrtl[2]
      z_vrt <- vrtl[3] + vrtl[4]
      test_vrt <- as.data.frame(cbind(x_vrt, y_vrt, z_vrt))
      x_vrt1 <- vrtl[2]
      y_vrt1 <- vrtl[3]
      z_vrt1 <- vrtl[1] + vrtl[4]
      test_vrt1 <- as.data.frame(cbind(x_vrt1, y_vrt1, z_vrt1))
      x_vrt2 <- vrtl[3]
      y_vrt2 <- vrtl[4]
      z_vrt2 <- vrtl[1] + vrtl[2]
      test_vrt2 <- as.data.frame(cbind(x_vrt2, y_vrt2, z_vrt2))
      x_vrt3 <- vrtl[4]
      y_vrt3 <- vrtl[1]
      z_vrt3 <- vrtl[2] + vrtl[3]
      test_vrt3 <- as.data.frame(cbind(x_vrt3, y_vrt3, z_vrt3))
      x_vrt4 <- vrtl[1]
      y_vrt4 <- vrtl[3]
      z_vrt4 <- vrtl[2] + vrtl[4]
      test_vrt4 <- as.data.frame(cbind(x_vrt4, y_vrt4, z_vrt4))
      x_vrt5 <- vrtl[2]
      y_vrt5 <- vrtl[4]
      z_vrt5 <- vrtl[1] + vrtl[3]
      test_vrt5 <- as.data.frame(cbind(x_vrt5, y_vrt5, z_vrt5))
      
      # Plotting
      # par(mfcol=c(6, n_col))  # Set up multi-plot layout
      # Plot original triangles
      plots[[i2]] <- TernaryPlot(xlim = c(-0.6, 0.6), tip.cex = 1, grid.lines = 4, grid.minor.lines = 1)
      if (cluster == TRUE) {
        if (nrow(test) > 0) TernaryPoints(test, col = if (cluster) alpha(color_palette[clusters_levels[t_names[[i2]]]], 0.5) else alpha(color_palette[i2], 0.5), cex = 0.1)
      } else {
        if (nrow(test) > 0) TernaryPoints(test, col = alpha('blue', 0.5), cex = 0.1)
      }
      if (vrtl_sol) {
        TernaryPoints(test_vrt,  col = alpha('red', 0.9), cex = 0.8, pch = 23, bg = "black", lwd = 2)
      }
      title(t_names[i2], cex.main = 3.5)
      
      TernaryPlot(xlim = c(-0.6, 0.6), tip.cex = 1, grid.lines = 4, grid.minor.lines = 1)
      if (cluster == TRUE) {
        if (nrow(test1) > 0) TernaryPoints(test1, col = if (cluster) alpha(color_palette[clusters_levels[t_names[[i2]]]], 0.5) else alpha(color_palette[i2], 0.5), cex = 0.1)
      } else {
        if (nrow(test1) > 0) TernaryPoints(test1, col = alpha('blue', 0.5), cex = 0.1)
      }
      if (vrtl_sol) {
        TernaryPoints(test_vrt1,  col = alpha('red', 0.9), cex = 0.8, pch = 23, bg = "black", lwd = 2)
      }
      TernaryPlot(xlim = c(-0.6, 0.6), tip.cex = 1, grid.lines = 4, grid.minor.lines = 1)
      if (cluster == TRUE) {
        if (nrow(test2) > 0) TernaryPoints(test2, col = if (cluster) alpha(color_palette[clusters_levels[t_names[[i2]]]], 0.5) else alpha(color_palette[i2], 0.5), cex = 0.1)
      } else {
        if (nrow(test2) > 0) TernaryPoints(test2, col = alpha('blue', 0.5), cex = 0.1)
      }
      if (vrtl_sol) {
        TernaryPoints(test_vrt2,  col = alpha('red', 0.9), cex = 0.8, pch = 23, bg = "black", lwd = 2)
      }
      TernaryPlot(xlim = c(-0.6, 0.6), tip.cex = 1, grid.lines = 4, grid.minor.lines = 1)
      if (cluster == TRUE) {
        if (nrow(test3) > 0) TernaryPoints(test3, col = if (cluster) alpha(color_palette[clusters_levels[t_names[[i2]]]], 0.5) else alpha(color_palette[i2], 0.5), cex = 0.1)
      } else {
        if (nrow(test3) > 0) TernaryPoints(test3, col = alpha('blue', 0.5), cex = 0.1)
      }
      if (vrtl_sol) {
        TernaryPoints(test_vrt3,  col = alpha('red', 0.9), cex = 0.8, pch = 23, bg = "black", lwd = 2)
      }
      TernaryPlot(xlim = c(-0.6, 0.6), tip.cex = 1, grid.lines = 4, grid.minor.lines = 1)
      # TernaryPoints(test4, col = alpha(color_palette[clusters_levels[t_names[[i2]]]], 0.5), cex = 0.1)
      if (cluster == TRUE) {
        if (nrow(test4) > 0) TernaryPoints(test4, col = if (cluster) alpha(color_palette[clusters_levels[t_names[[i2]]]], 0.5) else alpha(color_palette[i2], 0.5), cex = 0.1)
      } else {
        if (nrow(test4) > 0) TernaryPoints(test4, col = alpha('blue', 0.5), cex = 0.1)
      }
      if (vrtl_sol) {
        TernaryPoints(test_vrt4,  col = alpha('red', 0.9), cex = 0.8, pch = 23, bg = "black", lwd = 2)
      }
      TernaryPlot(xlim = c(-0.6, 0.6), tip.cex = 1, grid.lines = 4, grid.minor.lines = 1)
      if (cluster == TRUE) {
        if (nrow(test5) > 0) TernaryPoints(test5, col = if (cluster) alpha(color_palette[clusters_levels[t_names[[i2]]]], 0.5) else alpha(color_palette[i2], 0.5), cex = 0.1)
      } else {
        if (nrow(test5) > 0) TernaryPoints(test5, col = alpha('blue', 0.5), cex = 0.1)
      }
      if (vrtl_sol) {
        TernaryPoints(test_vrt5,  col = alpha('red', 0.9), cex = 0.8, pch = 23, bg = "black", lwd = 2)
      }
    }
  }
}

# --- Backwards Compatibility Aliases ---
#' @rdname Ternary_Plot
#' @export
Ternary_diagram <- Ternary_Plot

#' @rdname Ternary_Plot
#' @export
ternary_diagram <- Ternary_Plot